<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import { fetchRecruitmentPositionFilterOptions,fetchRecruitmentPositionLibrary,rebuildRecruitmentMatches } from '@/api/recruitment'
import { showError } from '@/api/http'
import type { RecruitmentPosition,RecruitmentPositionFilterOptions } from '@/types/model'
const router=useRouter(),loading=ref(false),total=ref(0),noticeCount=ref(0),latestUpdatedAt=ref<string|null>(null),rows=ref<RecruitmentPosition[]>([]),page=ref(1),expanded=reactive<Record<number,boolean>>({}),options=ref<RecruitmentPositionFilterOptions>({sources:[],notices:[],locations:[],organizations:[],educations:[],majorTypes:[]})
const pageSize=12,activeTab=ref<'all'|'match'|'uncertain'|'notMatch'|'favorites'>('all'),filters=reactive({sourceCode:'',location:'',organization:'',keyword:'',education:'',majorType:'',noticeId:undefined as number|undefined})
const grouped=computed(()=>{const map=new Map<number,{id:number;title:string;date:string|null;rows:RecruitmentPosition[]}>();rows.value.forEach(row=>{let group=map.get(row.noticeId);if(!group){group={id:row.noticeId,title:row.noticeTitle||`公告 #${row.noticeId}`,date:row.noticePublishDate,rows:[]};map.set(row.noticeId,group)}group.rows.push(row)});return [...map.values()]})
const notices=computed(()=>options.value.notices.filter(n=>!filters.sourceCode||n.sourceCode===filters.sourceCode))
function majorValue(){return filters.majorType==='不限专业'?'不限':filters.majorType==='有专业限制'?'__LIMITED__':''}
async function load(){if(activeTab.value==='favorites'){rows.value=[];total.value=0;return}loading.value=true;try{const status={all:undefined,match:'MATCH',uncertain:'UNCERTAIN',notMatch:'NOT_MATCH'} as const;const data=await fetchRecruitmentPositionLibrary({keyword:filters.keyword,location:filters.location,organization:filters.organization,education:filters.education,major:majorValue(),noticeId:filters.noticeId,matchStatus:status[activeTab.value as keyof typeof status],page:page.value,pageSize});rows.value=data.items;total.value=data.total;noticeCount.value=data.noticeCount;latestUpdatedAt.value=data.latestUpdatedAt}catch(e){showError(e,'读取招聘岗位库失败。')}finally{loading.value=false}}
async function loadOptions(){try{options.value=await fetchRecruitmentPositionFilterOptions()}catch(e){showError(e,'读取筛选项失败。')}}
function query(){page.value=1;load()}function reset(){Object.assign(filters,{sourceCode:'',location:'',organization:'',keyword:'',education:'',majorType:'',noticeId:undefined});query()}function sourceChange(){filters.noticeId=undefined}function changeTab(tab:string|number){activeTab.value=tab as typeof activeTab.value;query()}function changeLibraryType(value:string|number){router.push(value==='civil'?'/positions':'/positions/recruitment')}function changePage(value:number){page.value=value;load()}function openDetail(row:RecruitmentPosition){router.push({name:'recruitment-position-detail',params:{id:row.id},query:{from:'library'}})}async function rebuild(){loading.value=true;try{await rebuildRecruitmentMatches();await load()}catch(e){showError(e,'重新匹配失败。')}finally{loading.value=false}}function statusText(v:string|null|undefined){return v==='MATCH'?'可以报':v==='UNCERTAIN'?'待确认':v==='NOT_MATCH'?'不符合':'未分析'}function statusType(v:string|null|undefined){return v==='MATCH'?'success':v==='UNCERTAIN'?'warning':v==='NOT_MATCH'?'danger':'info'}function visible(group:{rows:RecruitmentPosition[]}){return expanded[group.rows[0].noticeId]?group.rows:group.rows.slice(0,3)}function summary(group:{rows:RecruitmentPosition[]}){const c={MATCH:0,UNCERTAIN:0,NOT_MATCH:0};group.rows.forEach(r=>{if(r.matchResult)c[r.matchResult as keyof typeof c]++});return c.MATCH+c.UNCERTAIN+c.NOT_MATCH?c:null}onMounted(async()=>{await loadOptions();await load()})
</script>
<template><section><div class="page-card library-bar"><h1 class="page-title">岗位库</h1><el-tabs model-value="recruitment" class="type-tabs" @tab-change="changeLibraryType"><el-tab-pane label="公务员岗位" name="civil"/><el-tab-pane label="招聘岗位" name="recruitment"/></el-tabs><el-tabs v-model="activeTab" class="position-tabs" @tab-change="changeTab"><el-tab-pane label="全部岗位" name="all"/><el-tab-pane label="适合我的" name="match"/><el-tab-pane label="待确认" name="uncertain"/><el-tab-pane label="不符合" name="notMatch"/><el-tab-pane label="我的收藏" name="favorites"/></el-tabs></div><div class="page-card result-head"><h2 class="page-title">招聘岗位</h2><div class="result-title"><p class="page-subtitle">共 {{total}} 个岗位，来自 {{noticeCount}} 篇招聘公告<span v-if="latestUpdatedAt"> · 最近更新：{{latestUpdatedAt.replace('T',' ')}}</span></p><el-button size="small" type="primary" plain @click="rebuild">重新分析资格</el-button></div><el-form v-if="activeTab==='all'" class="filter-form" label-position="top" @submit.prevent="query"><div class="filter-grid"><el-form-item label="来源平台"><el-select v-model="filters.sourceCode" clearable placeholder="全部" @change="sourceChange"><el-option v-for="item in options.sources" :key="item.sourceCode" :label="item.sourceName" :value="item.sourceCode"/></el-select></el-form-item><el-form-item label="来源公告"><el-select v-model="filters.noticeId" filterable clearable placeholder="全部公告"><el-option v-for="item in notices" :key="item.noticeId" :label="item.title" :value="item.noticeId"/></el-select></el-form-item><el-form-item label="地区"><el-select v-model="filters.location" filterable clearable placeholder="全部"><el-option v-for="item in options.locations" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="学历要求"><el-select v-model="filters.education" clearable placeholder="全部"><el-option v-for="item in options.educations" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="招聘单位"><el-select v-model="filters.organization" filterable clearable placeholder="全部"><el-option v-for="item in options.organizations" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="专业要求"><el-select v-model="filters.majorType" clearable placeholder="全部"><el-option v-for="item in options.majorTypes" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="岗位名称"><el-input v-model="filters.keyword" clearable placeholder="搜索岗位名称"/></el-form-item></div><div class="filter-actions"><el-button @click="reset">重置</el-button><el-button type="primary" @click="query">查询</el-button></div></el-form></div><div v-loading="loading" class="groups"><el-empty v-if="activeTab==='favorites'" description="招聘岗位收藏功能建设中"/><el-empty v-else-if="!grouped.length&&!loading" description="当前筛选条件下没有招聘岗位"/><article v-for="group in grouped" :key="group.id" class="notice-group"><header><h2>{{group.title}}</h2><p>{{group.date?.replace('T',' ')||'发布时间未提供'}} · 共 {{group.rows.length}} 个岗位 <template v-if="summary(group)">· 可以报 {{summary(group)?.MATCH}} · 待确认 {{summary(group)?.UNCERTAIN}} · 不符合 {{summary(group)?.NOT_MATCH}}</template></p></header><div v-for="row in visible(group)" :key="row.id" class="position-row"><div><div class="title"><el-tag :type="statusType(row.matchResult)" effect="plain">{{statusText(row.matchResult)}}</el-tag><strong>{{row.positionName}}</strong><el-tag v-if="row.recruitCount!=null" effect="plain">招聘 {{row.recruitCount}} 人</el-tag></div><p>{{[row.organizationName,row.departmentName].filter(Boolean).join(' · ')}}</p><small>{{[row.workLocation,row.educationRequirement,row.majorRequirement].filter(Boolean).join(' · ')}}</small></div><el-button type="primary" plain @click="openDetail(row)">查看详情</el-button></div><el-button v-if="group.rows.length>3" link type="primary" @click="expanded[group.id]=!expanded[group.id]">{{expanded[group.id]? '收起':'展开全部'+group.rows.length+'个岗位'}}</el-button></article><div v-if="total" class="pager"><el-pagination background layout="total,prev,pager,next" :total="total" :page-size="pageSize" :current-page="page" @current-change="changePage"/></div></div></section></template>
<style scoped>.library-bar,.result-head{margin-bottom:18px}.result-title{display:flex;justify-content:space-between;align-items:center}.type-tabs{margin-top:4px}.position-tabs{margin-top:8px}.filter-form{margin-top:20px;padding-top:18px;border-top:1px solid #ebeef5}.filter-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 18px}.filter-grid :deep(.el-select),.filter-grid :deep(.el-input){width:100%}.filter-actions{text-align:right}.groups{min-height:260px}.notice-group{background:#fff;border:1px solid #ebeef5;border-radius:10px;padding:20px 22px;margin-bottom:14px}.notice-group h2{font-size:17px;margin:0}.notice-group header p,.position-row p,.position-row small{color:#606266;margin:8px 0}.position-row{border-top:1px solid #f0f2f5;padding:14px 0;display:flex;align-items:center;justify-content:space-between;gap:12px}.position-row .title{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.position-row small{display:block}.pager{text-align:right;margin:24px 0}@media(max-width:900px){.filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.position-row{align-items:flex-start;flex-direction:column}.position-row>.el-button{align-self:flex-end}}</style>
